<h1 class="page-title">Giỏ hàng của bạn</h1><?php if(!$items):?><div class="panel empty"><h2>Giỏ hàng đang trống</h2><p>Khám phá thiết bị dành cho bạn.</p><a href="/products" class="btn btn-primary">Tiếp tục mua sắm</a></div><?php else:?><div class="panel table-wrap"><table class="table"><thead><tr><th>Sản phẩm</th><th>Đơn giá</th><th>Số lượng</th><th>Thành tiền</th><th></th></tr></thead><tbody><?php foreach($items as $p):?><tr><td><a href="/products/<?= $p['id'] ?>"><?= e($p['name']) ?></a><small class="d-block muted">Tồn kho: <?= $p['stock'] ?></small></td><td><?= money($p['price']) ?></td><td><form action="/cart/update" method="post" data-ajax data-reload="true" class="d-flex gap-2"><?= App\Core\Csrf::field() ?><input type="hidden" name="product_id" value="<?= $p['id'] ?>"><input type="hidden" name="action" value="set"><input class="form-control quantity" name="quantity" type="number" min="0" max="<?= $p['stock'] ?>" value="<?= $p['quantity'] ?>" aria-label="Số lượng <?= e($p['name']) ?>"><button type="submit" class="btn btn-light">Lưu</button></form></td><td><?= money($p['subtotal']) ?></td><td><form action="/cart/update" method="post" data-ajax data-reload="true"><?= App\Core\Csrf::field() ?><input type="hidden" name="product_id" value="<?= $p['id'] ?>"><input type="hidden" name="action" value="remove"><button class="btn btn-light" type="submit">Xóa</button></form></td></tr><?php endforeach?></tbody></table><div class="text-end"><p class="muted">Tổng thanh toán</p><h2><?= money($total) ?></h2><a href="/checkout" class="btn btn-primary mt-3">Tiến hành đặt hàng ↗</a></div></div><?php endif?>
